  [88756] = { "Riportare il botto", "Recupera $N1 ⟦Stolen Explosives=Esplosivi Rubati⟧ dagli accampamenti dei nani Ferroscuro.", "I Ferroscuro hanno qualche accampamento a est di qui, sul ⟦Direforge Hill=Colle Forgiatroce⟧, e hanno rubato un bel po' d'esplosivi dal nostro cantiere e se li son portati nelle tende.\n\nNon c'è bisogno che ti dica che razza di guai possono combinare i Ferroscuro con un barile di polvere!\n\nLo so che i Ferroscuro son pericolosi, ma ci servono quei barili. Li distingui dagli altri per i segni rossi che ci son sopra. Non possiamo lasciarli ai Ferroscuro!", nil, nil, 0xc57287cb, 0x0a061175, 0xf19bd9f0, nil, nil, "...mm" },
  [88757] = { "Effetti smarriti", "Riporta Essene's Necklace, ⟦Essene's Spellbook=Grimorio di Essene⟧ ed ⟦Essene's Waterskin=Borraccia di Essene⟧.", "Mentre fuggivo da quei Ferroscuro, ho finito per perdere un sacco della mia roba!\n\nPare che io abbia perso... la mia borraccia di cuoio verde, il mio libro degli incantesimi, la mia collana e... be', queste cose mi servono!\n\nSe riesci a trovarle mentre rifaccio i bagagli e riprendo fiato, mi saresti di grande aiuto.", nil, nil, 0xb1b07501, 0x8dd0b2c0, 0xd5dd92b9, nil, nil, "...mm" },
  [88758] = { "Sentimenti smarriti", "Riporta il biglietto di Essene a Corma Villard.", "Devo solo finire di rifare i bagagli e poi posso andarmene da qui!\n\nSe vuoi farmi un ultimo favore, ecco: porta questo biglietto a Corma. Così saprà che sono viva e che sto arrivando!", nil, nil, 0x4c47fdf9, 0x12fd10da, 0x3d2951ce, nil, nil, "...mm" },
