  [88809] = { "La salvaguardia di Eldarath", "Raccogli $N1 Reliquia di Eldarath da Guardiaserpe Sferzarabbia, Sirena Sferzarabbia e Mirmidone Sferzarabbia, e la Testa di Sire Sarthiss, per il Comandante Cantovero ad Azshara.", nil, nil, nil, 0x3265e3cf, 0xdeed3688, nil, nil, nil, "..mmm" },
